# frozen_string_literal: true

require "test_helper"
require "fileutils"
require "rails/generators"
require "tmpdir"
require "generators/quality_gate/install/install_generator"

module QualityGate
  # rubocop:disable Metrics/AbcSize
  class InstallGeneratorTest < Minitest::Test
    STRONG_MIGRATIONS_PROVENANCE = "# Generated by Quality Gate.\n"
    STRONG_MIGRATIONS_HEADER = <<~RUBY
      # frozen_string_literal: true

      require 'strong_migrations'

      # Generated by Quality Gate.
    RUBY
    INVALID_STRONG_MIGRATIONS_BASELINES = [
      "_baseline",
      "_1",
      "_20_260_829_010_101",
      "20_260_829_010_101_",
      "20__260_829_010_101",
      "20_260_829_010_101 + 1"
    ].freeze
    MANAGED_FILES = %w[
      .quality_gate.yml
      .rubocop.yml
      config/initializers/bullet.rb
      config/initializers/strong_migrations.rb
      test/test_helper.rb
    ].freeze
    AGENT_FILES = %w[
      .claude/hooks/quality_gate_fast.rb
      .claude/hooks/quality_gate_verify_stop.rb
      .claude/settings.json
      CLAUDE.md
      AGENTS.md
    ].freeze

    def test_exposes_the_managed_paths_and_coverage_markers
      assert InstallGenerator.const_defined?(:FILES, false)
      assert_equal MANAGED_FILES + AGENT_FILES, InstallGenerator::FILES
      assert_predicate InstallGenerator::FILES, :frozen?
      assert_equal "# quality_gate coverage — start", InstallGenerator::MARKER_START
      assert_predicate InstallGenerator::MARKER_START, :frozen?
      assert_equal "# quality_gate coverage — end", InstallGenerator::MARKER_END
      assert_predicate InstallGenerator::MARKER_END, :frozen?
    end

    def test_clean_host_receives_all_five_artifacts_and_a_written_summary
      with_host do |host|
        original_helper = File.binread(File.join(host, "test/test_helper.rb"))

        stdout, stderr = run_generator(host)

        assert_empty stderr
        MANAGED_FILES.each { assert_path_exists File.join(host, _1) }
        assert_equal expected_template("quality_gate.yml.tt"), read(host, ".quality_gate.yml")
        assert_equal expected_template("rubocop.yml.tt"), read(host, ".rubocop.yml")
        assert_equal expected_template("bullet.rb.tt"), read(host, "config/initializers/bullet.rb")
        assert_equal "#{STRONG_MIGRATIONS_HEADER}StrongMigrations.start_after = 20_260_829_010_101\n",
                     read(host, "config/initializers/strong_migrations.rb")
        assert_equal expected_covered_helper(original_helper), read(host, "test/test_helper.rb")
        MANAGED_FILES.each { assert_match(/^  - #{Regexp.escape(_1)}$/, stdout) }
        assert_match(/^Written:$/, stdout)
        assert_equal "Next: bundle exec quality_gate fast", stdout.lines.last.chomp
      end
    end

    def test_default_install_skips_agent_integration_and_reports_the_opt_in_hint
      with_host do |host|
        stdout, stderr = run_generator(host)

        assert_empty stderr
        %w[
          .claude/hooks/quality_gate_fast.rb
          .claude/hooks/quality_gate_verify_stop.rb
          .claude/settings.json
          CLAUDE.md
          AGENTS.md
        ].each { refute_path_exists File.join(host, _1) }
        assert_includes summary_entries(stdout, "Skipped"),
                        "agent integration (pass --agents to install Claude hooks and contracts)"
      end
    end

    def test_default_install_preserves_existing_agent_files
      with_host do |host|
        agent_files = {
          ".claude/hooks/quality_gate_fast.rb" => "#!/usr/bin/env ruby\n# custom fast hook\n",
          ".claude/hooks/quality_gate_verify_stop.rb" => "#!/usr/bin/env ruby\n# custom stop hook\n",
          ".claude/settings.json" => "{\"hooks\": {}}\n",
          "CLAUDE.md" => "# Claude notes\n",
          "AGENTS.md" => "# Agent notes\n"
        }
        agent_files.each do |relative_path, content|
          path = File.join(host, relative_path)
          FileUtils.mkdir_p(File.dirname(path))
          File.binwrite(path, content)
        end
        before = agent_files.to_h { |relative_path, _content| [relative_path, read(host, relative_path)] }

        stdout, stderr = run_generator(host)

        assert_empty stderr
        after = agent_files.to_h { |relative_path, _content| [relative_path, read(host, relative_path)] }
        assert_equal before, after
        assert_includes summary_entries(stdout, "Skipped"),
                        "agent integration (pass --agents to install Claude hooks and contracts)"
      end
    end

    def test_second_run_preserves_contents_and_timestamps_and_reports_everything_unchanged
      with_host do |host|
        run_generator(host)
        MANAGED_FILES.each_with_index do |relative_path, index|
          timestamp = Time.at(1_700_000_000 + index)
          File.utime(timestamp, timestamp, File.join(host, relative_path))
        end
        before = managed_snapshot(host)

        stdout, stderr = run_generator(host)

        assert_empty stderr
        assert_equal before, managed_snapshot(host)
        assert_equal 1, read(host, "test/test_helper.rb").scan(InstallGenerator::MARKER_START.b).length
        assert_empty summary_entries(stdout, "Written")
        assert_equal MANAGED_FILES, summary_entries(stdout, "Unchanged")
        assert_equal "Next: bundle exec quality_gate fast", stdout.lines.last.chomp
      end
    end

    def test_strong_migrations_generated_baseline_stays_unchanged_after_newer_migrations_appear
      with_host do |host|
        run_generator(host)
        initializer_path = File.join(host, "config/initializers/strong_migrations.rb")
        original = File.binread(initializer_path)
        timestamp = Time.at(1_700_000_050)
        File.utime(timestamp, timestamp, initializer_path)
        File.binwrite(File.join(host, "db/migrate/20270829010101_add_status.rb"), "# fixture\n")

        stdout, stderr = run_generator(host)

        assert_empty stderr
