        assert_equal timestamp, File.mtime(initializer_path)
        assert_includes summary_entries(stdout, "Unchanged"), "config/initializers/strong_migrations.rb"
        refute_includes summary_entries(stdout, "Needs a person"), "config/initializers/strong_migrations.rb"
        refute_includes stdout, "StrongMigrations.start_after = 20_270_829_010_101"
      end
