    def test_customized_marked_strong_migrations_guidance_preserves_its_historical_baseline
      with_host do |host|
        initializer_path = File.join(host, "config/initializers/strong_migrations.rb")
        FileUtils.mkdir_p(File.dirname(initializer_path))
        custom = <<~RUBY
          #{STRONG_MIGRATIONS_PROVENANCE.chomp}
          # Developer-owned settings.
          StrongMigrations.start_after = 20240101000000
          StrongMigrations.lock_timeout = 5.seconds
        RUBY
        File.binwrite(initializer_path, custom)
        timestamp = Time.at(1_700_000_075)
        File.utime(timestamp, timestamp, initializer_path)

        stdout, stderr = run_generator(host)

        assert_empty stderr
        assert_equal custom, File.binread(initializer_path)
        assert_equal timestamp, File.mtime(initializer_path)
        expected = "#{STRONG_MIGRATIONS_HEADER}StrongMigrations.start_after = 20_240_101_000_000\n"
        assert_includes stdout, "Use these lines manually for config/initializers/strong_migrations.rb:\n#{expected}"
        refute_includes stdout, "StrongMigrations.start_after = 20_260_829_010_101"
        assert_includes summary_entries(stdout, "Needs a person"),
                        "config/initializers/strong_migrations.rb"
      end
    end

