    def test_invalid_strong_migrations_baseline_expressions_remain_developer_owned
      INVALID_STRONG_MIGRATIONS_BASELINES.each_with_index do |expression, index|
        with_host do |host|
          initializer_path = File.join(host, "config/initializers/strong_migrations.rb")
          FileUtils.mkdir_p(File.dirname(initializer_path))
          content = "# Developer-owned settings.\nStrongMigrations.start_after = #{expression}\n"
          File.binwrite(initializer_path, content)
          timestamp = Time.at(1_700_000_085 + index)
          File.utime(timestamp, timestamp, initializer_path)
          exception = nil
          stdout, stderr = begin
            run_generator(host)
          rescue StandardError => e
            exception = e
            ["", ""]
          end

          assert_nil exception, "#{expression.inspect} raised #{exception&.class}: #{exception&.message}"
          assert_empty stderr
          assert_equal [content, timestamp], [File.binread(initializer_path), File.mtime(initializer_path)]
          assert_includes summary_entries(stdout, "Needs a person"),
                          "config/initializers/strong_migrations.rb"
          assert_includes stdout, "StrongMigrations.start_after = 20_260_829_010_101"
        end
      end
    end

