        stdout, stderr = run_generator(host, "--skip-initializers", "--skip-coverage")

        assert_empty stderr
        assert_path_exists File.join(host, ".quality_gate.yml")
        assert_path_exists File.join(host, ".rubocop.yml")
        refute_path_exists File.join(host, "config/initializers/bullet.rb")
