          config/initializers/bullet.rb
          config/initializers/strong_migrations.rb
          test/test_helper.rb
        ], summary_entries(stdout, "Written")
        %w[config/initializers/bullet.rb config/initializers/strong_migrations.rb test/test_helper.rb].each do |path|
          refute_includes stdout, path
        end
        assert_equal "Next: bundle exec quality_gate fast", stdout.lines.last.chomp
      end
    end

