    def test_coverage_preserves_ruby_prologues_host_newlines_and_surrounding_bytes
      bom = "\xEF\xBB\xBF".b
      lf_prologue = <<~'RUBY'.b
        #!/usr/bin/env ruby

        # Copyright 2026 Example Authors.
        # Ordinary comments remain part of the source header.
        # shareable_constant_value: literal
        # warn_indent: true
        # -*- mode: ruby; coding: UTF-8; frozen_string_literal: true -*-

      RUBY
      crlf_prologue = lf_prologue.gsub("\n".b, "\r\n".b)
      block_comment_prologue = <<~'RUBY'.b
        =begin
        Host test-helper documentation.
        Coverage must remain after this non-executable block.
        =end

      RUBY
      lf_original = [bom, lf_prologue, "require \"host\"\n"].join.b
      lf_expected = [bom, lf_prologue, coverage_block("\n"), "require \"host\"\n"].join.b
      crlf_original = [crlf_prologue, "require \"host\"\r\n"].join.b
      crlf_expected = [crlf_prologue, coverage_block("\r\n"), "require \"host\"\r\n"].join.b
      block_original = block_comment_prologue + "require \"host\"\n".b
      block_expected = block_comment_prologue + coverage_block("\n") + "require \"host\"\n".b
      incomplete_block = "=begin\nHost documentation without a terminator.\nrequire \"host\"\n".b
      cases = {
        "BOM, ordinary comments, and complete directives" => [lf_original, lf_expected],
        "CRLF prologue" => [crlf_original, crlf_expected],
        "leading block comment" => [block_original, block_expected],
        "unterminated block comment" => [incomplete_block, coverage_block("\n") + incomplete_block],
        "empty helper" => ["".b, coverage_block("\n")],
        "no final newline" => ["require \"host\"".b, coverage_block("\n") + "require \"host\"".b]
      }

      cases.each do |name, (original, expected)|
        with_host do |host|
          File.binwrite(File.join(host, "test/test_helper.rb"), original)

          run_generator(host)

          assert_equal expected.b, read(host, "test/test_helper.rb"), name
        end
      end
    end

    def test_coverage_replaces_a_hard_link_without_mutating_the_external_inode
      with_host do |host, parent|
        helper_path = File.join(host, "test/test_helper.rb")
        original = File.binread(helper_path)
        File.chmod(0o740, helper_path)
        external_path = File.join(parent, "external-test-helper.rb")
        File.link(helper_path, external_path)
        original_inode = File.stat(external_path).ino

        stdout, stderr = run_generator(host)

        assert_empty stderr
        assert_equal original, File.binread(external_path)
        assert_equal original_inode, File.stat(external_path).ino
        refute_equal original_inode, File.stat(helper_path).ino
        assert_equal 0o740, File.stat(helper_path).mode & 0o777
        assert_equal expected_covered_helper(original), File.binread(helper_path)
        assert_includes summary_entries(stdout, "Written"), "test/test_helper.rb"
      end
    end

    def test_coverage_write_failure_preserves_the_original_and_continues
      with_host do |host|
        helper_path = File.join(host, "test/test_helper.rb")
        test_directory = File.dirname(helper_path)
        original = [File.binread(helper_path), File.stat(helper_path).ino, File.stat(helper_path).mode]
        exception = nil
        File.chmod(0o555, test_directory)
        stdout, stderr = begin
          run_generator(host)
        rescue StandardError => e
          exception = e
          ["", ""]
        ensure
          File.chmod(0o755, test_directory)
        end

        assert_nil exception
        assert_empty stderr
        assert_equal original, [File.binread(helper_path), File.stat(helper_path).ino, File.stat(helper_path).mode]
        assert_equal ["test/test_helper.rb"], summary_entries(stdout, "Needs a person")
        assert_equal MANAGED_FILES - ["test/test_helper.rb"], summary_entries(stdout, "Written")
        assert_empty Dir.glob(File.join(test_directory, ".quality_gate-coverage-*"))
        assert_equal "Next: bundle exec quality_gate fast", stdout.lines.last.chomp
      end
    end

    def test_symlinked_managed_directory_cannot_write_outside_the_host_root
      with_host do |host, parent|
        outside_config = File.join(parent, "outside-config")
        FileUtils.mkdir_p(File.join(outside_config, "initializers"))
        sentinel = File.join(parent, "sentinel.txt")
        File.binwrite(sentinel, "keep me\n")
        File.symlink(outside_config, File.join(host, "config"))
        before = outside_snapshot(parent, host)

        stdout, stderr = run_generator(host)

        assert_empty stderr
        assert_equal before, outside_snapshot(parent, host)
        assert_equal "keep me\n", File.binread(sentinel)
        assert_equal ["config/initializers/bullet.rb", "config/initializers/strong_migrations.rb"],
                     summary_entries(stdout, "Needs a person")
        assert_equal MANAGED_FILES - %w[config/initializers/bullet.rb config/initializers/strong_migrations.rb],
                     summary_entries(stdout, "Written")
        refute_path_exists File.join(outside_config, "initializers/bullet.rb")
        refute_path_exists File.join(outside_config, "initializers/strong_migrations.rb")
      end
    end

    def test_directory_at_a_managed_file_path_needs_a_person_and_does_not_stop_installation
      with_host do |host|
        occupied_path = File.join(host, ".quality_gate.yml")
        FileUtils.mkdir(occupied_path)
        File.binwrite(File.join(occupied_path, "sentinel.txt"), "keep me\n")

        stdout, stderr = run_generator(host)

        assert_empty stderr
        assert_predicate File.lstat(occupied_path), :directory?
        assert_equal "keep me\n", File.binread(File.join(occupied_path, "sentinel.txt"))
        assert_equal [".quality_gate.yml"], summary_entries(stdout, "Needs a person")
        assert_equal MANAGED_FILES - [".quality_gate.yml"], summary_entries(stdout, "Written")
      end
    end

    def test_regular_file_parent_needs_a_person_for_children_and_does_not_stop_installation
      with_host do |host|
        parent_path = File.join(host, "config")
        File.binwrite(parent_path, "developer-owned\n")
        exception = nil
        stdout, stderr = begin
          run_generator(host)
        rescue StandardError => e
          exception = e
          ["", ""]
        end

        assert_nil exception
        assert_empty stderr
        assert_equal "developer-owned\n", File.binread(parent_path)
        assert_equal ["config/initializers/bullet.rb", "config/initializers/strong_migrations.rb"],
                     summary_entries(stdout, "Needs a person")
        assert_equal MANAGED_FILES - %w[config/initializers/bullet.rb config/initializers/strong_migrations.rb],
                     summary_entries(stdout, "Written")
      end
    end

    def test_symlinked_destination_root_cannot_write_into_its_target
      Dir.mktmpdir("quality-gate-symlinked-root") do |parent|
        outside = File.join(parent, "outside")
        FileUtils.mkdir_p(File.join(outside, "test"))
        FileUtils.mkdir_p(File.join(outside, "db/migrate"))
        File.binwrite(File.join(outside, "test/test_helper.rb"), "require \"host\"\n")
        File.binwrite(File.join(outside, "sentinel.txt"), "keep me\n")
        host = File.join(parent, "host")
        File.symlink(outside, host)
        before = outside_snapshot(parent, host)

        stdout, stderr = run_generator(host)

        assert_empty stderr
        assert_equal before, outside_snapshot(parent, host)
        assert_equal MANAGED_FILES, summary_entries(stdout, "Needs a person")
        assert_empty summary_entries(stdout, "Written")
        assert_equal "Next: bundle exec quality_gate fast", stdout.lines.last.chomp
      end
    end

    private

    def with_host(test_helper: true)
      Dir.mktmpdir("quality-gate-install") do |parent|
        host = File.join(parent, "host")
        FileUtils.mkdir_p(File.join(host, "db/migrate"))
        if test_helper
          FileUtils.mkdir_p(File.join(host, "test"))
          File.binwrite(File.join(host, "test/test_helper.rb"), <<~RUBY)
            require_relative "../config/environment"
            require "rails/test_help"
          RUBY
        end
        File.binwrite(File.join(host, "db/migrate/20260829010101_create_accounts.rb"), "# fixture\n")
        yield host, parent
      end
    end

    def run_generator(host, *arguments, behavior: :invoke)
      capture_io { InstallGenerator.start(arguments, destination_root: host, behavior:) }
    end

    def read(host, relative_path)
      File.binread(File.join(host, relative_path))
    end

    def expected_template(name)
      File.binread(File.join(InstallGenerator.source_root, name))
    end

    def expected_covered_helper(original_helper)
      coverage_block("\n") + original_helper
    end

    def coverage_block(newline)
      template = expected_template("simplecov.rb.tt").gsub("\n", newline)
      "#{InstallGenerator::MARKER_START}#{newline}#{template}#{InstallGenerator::MARKER_END}#{newline}".b
    end

    def managed_snapshot(host)
      MANAGED_FILES.to_h do |relative_path|
        path = File.join(host, relative_path)
        [relative_path, [File.binread(path), File.mtime(path)]]
      end
    end

    def summary_entries(stdout, heading)
      lines = stdout.lines.map(&:chomp)
      start = lines.index("#{heading}:")
      return [] unless start

      lines.drop(start + 1).take_while { _1.start_with?("  - ") }.map { _1.delete_prefix("  - ") }
    end

    def outside_snapshot(parent, host)
      Dir.glob(File.join(parent, "**/*"), File::FNM_DOTMATCH).filter_map do |path|
        next unless File.file?(path)
        next if path == host || path.start_with?("#{host}/")

        [path, File.binread(path)]
      end.to_h
    end

    def tree_snapshot(root)
      Dir.glob(File.join(root, "**/*"), File::FNM_DOTMATCH).sort.to_h do |path|
        stat = File.lstat(path)
        relative_path = path.delete_prefix("#{root}/")
        content = File.binread(path) if stat.file?
        [relative_path, [stat.ftype, stat.mode, stat.mtime, content]]
      end
    end
  end
  # rubocop:enable Metrics/AbcSize
end
